<?php require 'includes/bootstrap.php'; if($_SERVER['REQUEST_METHOD']==='POST'){$q=$pdo->prepare('SELECT * FROM admin WHERE username=?');$q->execute([trim($_POST['username']??'')]);$a=$q->fetch();if($a && password_verify($_POST['password']??'',$a['password'])){session_regenerate_id(true);$_SESSION['role']='admin';$_SESSION['user_id']=$a['id'];$_SESSION['display_name']='Administrator';go('admin_dashboard.php');}flash('Invalid admin username or password.');} page_start('Admin Login'); ?>
<div class="vc-card" style="max-width:520px;margin:auto"><h2>Administrator Login</h2><form method="post"><?php field('username','Username');field('password','Password','password');?><button class="btn btn-dark">Login</button></form></div><?php page_end(); ?>
